# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Avery", "Sam")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Avery, Sam | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seat_count_raises(self):
        people = [make("Avery", "Sam")]
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows(people, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)


if __name__ == "__main__":
    unittest.main()
